// Summarises a reviewed run and writes study-source report options.
// Usage: node post-review.mjs RUN_DIR STUDY_FILE OPTIONS_OUT.json
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const [run, studyFile, out] = process.argv.slice(2);
const jl = (f) =>
  readFileSync(path.join(run, f), "utf8")
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));
const inv = jl("inventory.jsonl");
const checks = jl("checks.jsonl");
const name = (id) => {
  const i = inv.find((x) => x.itemId === id);
  return i.path ? path.basename(i.path) : i.uri;
};
const tally = {};
for (const c of checks) tally[c.status] = (tally[c.status] || 0) + 1;
console.log("checks", checks.length, tally);
for (const i of inv) {
  const mine = checks.filter((c) => c.itemId === i.itemId);
  const t = {};
  for (const c of mine) t[c.status] = (t[c.status] || 0) + 1;
  console.log(name(i.itemId), i.itemId.slice(0, 8), i.state, JSON.stringify(t));
  for (const c of mine.filter((c) => c.status !== "unknown"))
    console.log("   ", c.ruleId, c.status);
}
const findings = JSON.parse(readFileSync(path.join(run, "findings.json"), "utf8"));
console.log("findings", (findings.findings ?? findings).length);

const sourceText = readFileSync(studyFile, "utf8");
const lines = sourceText.split(/\r?\n/);
const options = {
